export interface ServerCredentials {
  host: string;
  port: number;
  /** true = implicit TLS (465 / 993); false = STARTTLS upgrade (587 / 143). */
  secure: boolean;
  username: string;
  password: string;
}

export interface OutgoingEmail {
  from: { name: string; address: string };
  to: string;
  subject: string;
  text: string;
  /** Full RFC Message-ID with angle brackets, generated by the caller so it can be stored first. */
  messageId: string;
  headers: Record<string, string>;
}

export interface SendResult {
  messageId: string;
  response: string;
}

/** A message read from a mailbox's INBOX, reduced to what classification needs. */
export interface InboundMessage {
  uid: number;
  from: string | null;
  subject: string;
  inReplyTo: string | null;
  references: string[];
  /** Lower-cased header name → value, for the few headers we inspect. */
  headers: Record<string, string>;
  contentType: string;
  text: string;
  /** Raw source (possibly truncated). Bounces quote the original headers here. */
  raw: string;
}
